question.solution:
def gcd(a, b):
    x, y = abs(int(a)), abs(int(b))
    while y:
        x, y = y, x % y
    return x


def lcm(a, b):
    x, y = abs(int(a)), abs(int(b))
    if x == 0 or y == 0:
        return 0
    return x * y // gcd(x, y)


print(gcd(12, 18))
print(lcm(4, 6))
print(lcm(0, 5))
